-- TCP SecureGate — initial schema
-- Conventions:
--   * Timestamps are ISO-8601 UTC strings generated by the server (authoritative).
--   * Calendar dates (visit dates, validity dates) are YYYY-MM-DD in the
--     establishment's configured time zone.
--   * movement_events, event_corrections and audit_events are append-only and
--     protected by triggers.

-- ---------------------------------------------------------------------------
-- Organization structure
-- ---------------------------------------------------------------------------

CREATE TABLE organizations (
  id            INTEGER PRIMARY KEY,
  code          TEXT NOT NULL UNIQUE,
  name          TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE locations (
  id              INTEGER PRIMARY KEY,
  organization_id INTEGER NOT NULL REFERENCES organizations(id),
  code            TEXT NOT NULL,
  name            TEXT NOT NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('HQ', 'LOCATION')),
  address_note    TEXT,
  is_active       INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  UNIQUE (organization_id, code)
);

CREATE TABLE gates (
  id           INTEGER PRIMARY KEY,
  location_id  INTEGER NOT NULL REFERENCES locations(id),
  code         TEXT NOT NULL,
  name         TEXT NOT NULL,
  gate_type    TEXT NOT NULL CHECK (gate_type IN ('MAIN', 'PEDESTRIAN', 'VEHICLE', 'SERVICE')),
  is_active    INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  UNIQUE (location_id, code)
);

-- ---------------------------------------------------------------------------
-- Identity, roles & sessions
-- ---------------------------------------------------------------------------

CREATE TABLE roles (
  code         TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  description  TEXT NOT NULL,
  rank         INTEGER NOT NULL
);

CREATE TABLE permissions (
  code         TEXT PRIMARY KEY,
  group_name   TEXT NOT NULL,
  description  TEXT NOT NULL
);

CREATE TABLE role_permissions (
  role_code        TEXT NOT NULL REFERENCES roles(code),
  permission_code  TEXT NOT NULL REFERENCES permissions(code),
  PRIMARY KEY (role_code, permission_code)
);

CREATE TABLE users (
  id                   INTEGER PRIMARY KEY,
  organization_id      INTEGER NOT NULL REFERENCES organizations(id),
  username             TEXT NOT NULL COLLATE NOCASE UNIQUE,
  display_name         TEXT NOT NULL,
  designation          TEXT,
  department           TEXT,
  role_code            TEXT NOT NULL REFERENCES roles(code),
  password_hash        TEXT NOT NULL,
  all_locations        INTEGER NOT NULL DEFAULT 0 CHECK (all_locations IN (0, 1)),
  primary_location_id  INTEGER REFERENCES locations(id),
  assigned_gate_id     INTEGER REFERENCES gates(id),
  is_active            INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  is_demo              INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
  failed_login_count   INTEGER NOT NULL DEFAULT 0,
  locked_until         TEXT,
  last_login_at        TEXT,
  password_changed_at  TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);
CREATE INDEX users_org_role ON users (organization_id, role_code);

CREATE TABLE user_locations (
  user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  location_id  INTEGER NOT NULL REFERENCES locations(id),
  PRIMARY KEY (user_id, location_id)
);
CREATE INDEX user_locations_location ON user_locations (location_id);

CREATE TABLE sessions (
  id            INTEGER PRIMARY KEY,
  token_hash    TEXT NOT NULL UNIQUE,
  user_id       INTEGER NOT NULL REFERENCES users(id),
  created_at    TEXT NOT NULL,
  last_seen_at  TEXT NOT NULL,
  expires_at    TEXT NOT NULL,
  revoked_at    TEXT,
  ip            TEXT,
  user_agent    TEXT
);
CREATE INDEX sessions_user ON sessions (user_id);

CREATE TABLE settings (
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  key              TEXT NOT NULL,
  value            TEXT NOT NULL,
  updated_by       INTEGER REFERENCES users(id),
  updated_at       TEXT NOT NULL,
  PRIMARY KEY (organization_id, key)
);

CREATE TABLE ref_sequences (
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  prefix           TEXT NOT NULL,
  year             INTEGER NOT NULL,
  last_value       INTEGER NOT NULL,
  PRIMARY KEY (organization_id, prefix, year)
);

-- ---------------------------------------------------------------------------
-- Personnel
-- ---------------------------------------------------------------------------

CREATE TABLE personnel (
  id                   INTEGER PRIMARY KEY,
  organization_id      INTEGER NOT NULL REFERENCES organizations(id),
  service_number       TEXT NOT NULL COLLATE NOCASE,
  full_name            TEXT NOT NULL,
  rank                 TEXT,
  designation          TEXT,
  unit                 TEXT,
  department           TEXT,
  primary_location_id  INTEGER NOT NULL REFERENCES locations(id),
  status               TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE')),
  status_reason        TEXT,
  access_valid_from    TEXT,
  access_valid_until   TEXT,
  notes                TEXT,
  created_by           INTEGER REFERENCES users(id),
  updated_by           INTEGER REFERENCES users(id),
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  UNIQUE (organization_id, service_number),
  CHECK (access_valid_until IS NULL OR access_valid_from IS NULL OR access_valid_until >= access_valid_from)
);
CREATE INDEX personnel_location_status ON personnel (primary_location_id, status);
CREATE INDEX personnel_name ON personnel (full_name);
CREATE INDEX personnel_unit ON personnel (unit);

CREATE TABLE personnel_locations (
  personnel_id  INTEGER NOT NULL REFERENCES personnel(id) ON DELETE CASCADE,
  location_id   INTEGER NOT NULL REFERENCES locations(id),
  PRIMARY KEY (personnel_id, location_id)
);
CREATE INDEX personnel_locations_location ON personnel_locations (location_id);

-- ---------------------------------------------------------------------------
-- Contractors, vendors & service personnel
-- ---------------------------------------------------------------------------

CREATE TABLE contractor_companies (
  id               INTEGER PRIMARY KEY,
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  name             TEXT NOT NULL,
  category         TEXT NOT NULL CHECK (category IN ('CONTRACTOR', 'VENDOR', 'SERVICE')),
  contact_name     TEXT,
  contact_phone    TEXT,
  contact_email    TEXT,
  status           TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE')),
  notes            TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (organization_id, name)
);

CREATE TABLE contractors (
  id                     INTEGER PRIMARY KEY,
  organization_id        INTEGER NOT NULL REFERENCES organizations(id),
  company_id             INTEGER NOT NULL REFERENCES contractor_companies(id),
  reference              TEXT NOT NULL,
  full_name              TEXT NOT NULL,
  category               TEXT NOT NULL CHECK (category IN ('CONTRACTOR', 'VENDOR', 'SERVICE')),
  phone                  TEXT,
  sponsoring_department  TEXT NOT NULL,
  sponsor_user_id        INTEGER REFERENCES users(id),
  purpose                TEXT NOT NULL,
  location_id            INTEGER NOT NULL REFERENCES locations(id),
  valid_from             TEXT NOT NULL,
  valid_until            TEXT NOT NULL,
  window_start           TEXT NOT NULL DEFAULT '00:00',
  window_end             TEXT NOT NULL DEFAULT '23:59',
  allowed_days           TEXT NOT NULL DEFAULT '1111111' CHECK (length(allowed_days) = 7),
  access_nonce           TEXT NOT NULL UNIQUE,
  status                 TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'CANCELLED')),
  status_reason          TEXT,
  notes                  TEXT,
  created_by             INTEGER REFERENCES users(id),
  created_at             TEXT NOT NULL,
  updated_at             TEXT NOT NULL,
  UNIQUE (organization_id, reference),
  CHECK (valid_until >= valid_from)
);
CREATE INDEX contractors_location ON contractors (location_id, status);
CREATE INDEX contractors_company ON contractors (company_id);
CREATE INDEX contractors_name ON contractors (full_name);

-- ---------------------------------------------------------------------------
-- Credentials (RFID/NFC — simulated in the prototype)
-- ---------------------------------------------------------------------------

CREATE TABLE credentials (
  id                 INTEGER PRIMARY KEY,
  organization_id    INTEGER NOT NULL REFERENCES organizations(id),
  credential_number  TEXT NOT NULL COLLATE NOCASE,
  credential_type    TEXT NOT NULL CHECK (credential_type IN ('RFID_CARD', 'NFC_CARD', 'NFC_TAG', 'TEMPORARY_CARD')),
  holder_type        TEXT NOT NULL CHECK (holder_type IN ('PERSONNEL', 'CONTRACTOR')),
  personnel_id       INTEGER REFERENCES personnel(id),
  contractor_id      INTEGER REFERENCES contractors(id),
  status             TEXT NOT NULL CHECK (status IN ('ACTIVE', 'INACTIVE', 'BLOCKED', 'LOST', 'REPLACED', 'EXPIRED')),
  is_temporary       INTEGER NOT NULL DEFAULT 0 CHECK (is_temporary IN (0, 1)),
  valid_from         TEXT NOT NULL,
  valid_until        TEXT,
  status_reason      TEXT,
  replaces_id        INTEGER REFERENCES credentials(id),
  replaced_by_id     INTEGER REFERENCES credentials(id),
  issued_by          INTEGER REFERENCES users(id),
  issued_at          TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  UNIQUE (organization_id, credential_number),
  CHECK (
    (holder_type = 'PERSONNEL' AND personnel_id IS NOT NULL AND contractor_id IS NULL) OR
    (holder_type = 'CONTRACTOR' AND contractor_id IS NOT NULL AND personnel_id IS NULL)
  ),
  CHECK (valid_until IS NULL OR valid_until > valid_from)
);
-- At most one active permanent and one active temporary credential per holder.
CREATE UNIQUE INDEX credentials_active_personnel ON credentials (personnel_id, is_temporary)
  WHERE status = 'ACTIVE' AND personnel_id IS NOT NULL;
CREATE UNIQUE INDEX credentials_active_contractor ON credentials (contractor_id, is_temporary)
  WHERE status = 'ACTIVE' AND contractor_id IS NOT NULL;
CREATE INDEX credentials_status ON credentials (organization_id, status);

CREATE TABLE credential_history (
  id             INTEGER PRIMARY KEY,
  credential_id  INTEGER NOT NULL REFERENCES credentials(id),
  action         TEXT NOT NULL,
  from_status    TEXT,
  to_status      TEXT,
  reason         TEXT,
  actor_user_id  INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL
);
CREATE INDEX credential_history_credential ON credential_history (credential_id, created_at);

-- ---------------------------------------------------------------------------
-- Temporary access
-- ---------------------------------------------------------------------------

CREATE TABLE temporary_access (
  id                   INTEGER PRIMARY KEY,
  organization_id      INTEGER NOT NULL REFERENCES organizations(id),
  reference            TEXT NOT NULL,
  location_id          INTEGER NOT NULL REFERENCES locations(id),
  holder_type          TEXT NOT NULL CHECK (holder_type IN ('PERSONNEL', 'CONTRACTOR', 'INDIVIDUAL')),
  personnel_id         INTEGER REFERENCES personnel(id),
  contractor_id        INTEGER REFERENCES contractors(id),
  holder_name          TEXT NOT NULL,
  holder_organization  TEXT,
  holder_phone         TEXT,
  reason               TEXT NOT NULL,
  sponsoring_department TEXT,
  valid_from           TEXT NOT NULL,
  valid_until          TEXT NOT NULL,
  access_nonce         TEXT NOT NULL UNIQUE,
  status               TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'REVOKED')),
  revoked_reason       TEXT,
  revoked_by           INTEGER REFERENCES users(id),
  revoked_at           TEXT,
  issued_by            INTEGER REFERENCES users(id),
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  UNIQUE (organization_id, reference),
  CHECK (valid_until > valid_from),
  CHECK (
    (holder_type = 'PERSONNEL' AND personnel_id IS NOT NULL) OR
    (holder_type = 'CONTRACTOR' AND contractor_id IS NOT NULL) OR
    (holder_type = 'INDIVIDUAL')
  )
);
CREATE INDEX temporary_access_location ON temporary_access (location_id, status, valid_until);

-- ---------------------------------------------------------------------------
-- Vehicles
-- ---------------------------------------------------------------------------

CREATE TABLE vehicles (
  id                      INTEGER PRIMARY KEY,
  organization_id         INTEGER NOT NULL REFERENCES organizations(id),
  registration_number     TEXT NOT NULL,
  display_registration    TEXT NOT NULL,
  category                TEXT NOT NULL,
  make_model              TEXT,
  colour                  TEXT,
  owner_type              TEXT NOT NULL CHECK (owner_type IN ('PERSONNEL', 'VISITOR', 'CONTRACTOR', 'DELIVERY', 'ESTABLISHMENT', 'OTHER')),
  personnel_id            INTEGER REFERENCES personnel(id),
  contractor_id           INTEGER REFERENCES contractors(id),
  visitor_id              INTEGER,
  owner_name              TEXT,
  registered_location_id  INTEGER NOT NULL REFERENCES locations(id),
  authorization_status    TEXT NOT NULL DEFAULT 'PENDING' CHECK (authorization_status IN ('AUTHORIZED', 'PENDING', 'NOT_AUTHORIZED', 'BLOCKED')),
  authorized_until        TEXT,
  notes                   TEXT,
  created_by              INTEGER REFERENCES users(id),
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  UNIQUE (organization_id, registration_number)
);
CREATE INDEX vehicles_location ON vehicles (registered_location_id);

CREATE TABLE vehicle_locations (
  vehicle_id   INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
  location_id  INTEGER NOT NULL REFERENCES locations(id),
  PRIMARY KEY (vehicle_id, location_id)
);

-- ---------------------------------------------------------------------------
-- Visitors, visits, approvals & passes
-- ---------------------------------------------------------------------------

CREATE TABLE visitors (
  id               INTEGER PRIMARY KEY,
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  full_name        TEXT NOT NULL,
  company          TEXT,
  phone            TEXT,
  email            TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);
CREATE INDEX visitors_phone ON visitors (organization_id, phone);
CREATE INDEX visitors_name ON visitors (full_name);

CREATE TABLE visits (
  id                      INTEGER PRIMARY KEY,
  organization_id         INTEGER NOT NULL REFERENCES organizations(id),
  reference               TEXT NOT NULL,
  location_id             INTEGER NOT NULL REFERENCES locations(id),
  visitor_id              INTEGER NOT NULL REFERENCES visitors(id),
  source                  TEXT NOT NULL CHECK (source IN ('PRE_REGISTERED', 'WALK_IN')),
  host_user_id            INTEGER NOT NULL REFERENCES users(id),
  host_department         TEXT,
  approving_officer_id    INTEGER NOT NULL REFERENCES users(id),
  purpose                 TEXT NOT NULL,
  destination             TEXT NOT NULL,
  visit_date              TEXT NOT NULL,
  expected_arrival        TEXT NOT NULL,
  expected_departure      TEXT NOT NULL,
  vehicle_id              INTEGER REFERENCES vehicles(id),
  notes                   TEXT,
  status                  TEXT NOT NULL CHECK (status IN ('EXPECTED', 'ARRIVED', 'HOST_NOTIFIED', 'WAITING', 'APPROVED', 'INSIDE', 'OVERDUE', 'EXITED', 'REJECTED', 'CANCELLED', 'EXPIRED')),
  requires_security_check INTEGER NOT NULL DEFAULT 0 CHECK (requires_security_check IN (0, 1)),
  security_checked_by     INTEGER REFERENCES users(id),
  security_checked_at     TEXT,
  security_check_note     TEXT,
  host_acknowledged_by    INTEGER REFERENCES users(id),
  host_acknowledged_at    TEXT,
  arrived_at              TEXT,
  arrived_gate_id         INTEGER REFERENCES gates(id),
  entered_at              TEXT,
  exited_at               TEXT,
  cancelled_reason        TEXT,
  created_by              INTEGER NOT NULL REFERENCES users(id),
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  UNIQUE (organization_id, reference),
  CHECK (expected_departure > expected_arrival)
);
CREATE INDEX visits_location_status ON visits (location_id, status);
CREATE INDEX visits_location_date ON visits (location_id, visit_date);
CREATE INDEX visits_host ON visits (host_user_id);
CREATE INDEX visits_approver ON visits (approving_officer_id, status);
CREATE INDEX visits_visitor ON visits (visitor_id);

CREATE TABLE visit_status_history (
  id             INTEGER PRIMARY KEY,
  visit_id       INTEGER NOT NULL REFERENCES visits(id),
  from_status    TEXT,
  to_status      TEXT NOT NULL,
  reason         TEXT,
  actor_user_id  INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL
);
CREATE INDEX visit_status_history_visit ON visit_status_history (visit_id, created_at);

-- One final authorization decision per visit: prevents duplicate approvals.
CREATE TABLE visit_approvals (
  id                INTEGER PRIMARY KEY,
  visit_id          INTEGER NOT NULL UNIQUE REFERENCES visits(id),
  decision          TEXT NOT NULL CHECK (decision IN ('APPROVED', 'REJECTED')),
  reason            TEXT,
  reviewer_user_id  INTEGER NOT NULL REFERENCES users(id),
  created_at        TEXT NOT NULL
);

CREATE TABLE visit_passes (
  id              INTEGER PRIMARY KEY,
  visit_id        INTEGER NOT NULL REFERENCES visits(id),
  pass_number     TEXT NOT NULL UNIQUE,
  token_nonce     TEXT NOT NULL UNIQUE,
  status          TEXT NOT NULL CHECK (status IN ('ACTIVE', 'REVOKED', 'USED', 'EXPIRED')),
  single_use      INTEGER NOT NULL DEFAULT 1 CHECK (single_use IN (0, 1)),
  valid_from      TEXT NOT NULL,
  valid_until     TEXT NOT NULL,
  issued_by       INTEGER REFERENCES users(id),
  issued_at       TEXT NOT NULL,
  revoked_at      TEXT,
  revoked_by      INTEGER REFERENCES users(id),
  revoked_reason  TEXT,
  entry_used_at   TEXT,
  exit_used_at    TEXT,
  CHECK (valid_until > valid_from)
);
CREATE UNIQUE INDEX visit_passes_one_active ON visit_passes (visit_id) WHERE status = 'ACTIVE';

-- ---------------------------------------------------------------------------
-- Deliveries
-- ---------------------------------------------------------------------------

CREATE TABLE deliveries (
  id                      INTEGER PRIMARY KEY,
  organization_id         INTEGER NOT NULL REFERENCES organizations(id),
  reference               TEXT NOT NULL,
  location_id             INTEGER NOT NULL REFERENCES locations(id),
  gate_id                 INTEGER REFERENCES gates(id),
  category                TEXT NOT NULL,
  company                 TEXT NOT NULL,
  courier_name            TEXT NOT NULL,
  courier_phone           TEXT,
  vehicle_id              INTEGER REFERENCES vehicles(id),
  recipient_user_id       INTEGER REFERENCES users(id),
  recipient_name          TEXT,
  recipient_department    TEXT NOT NULL,
  sponsor_user_id         INTEGER REFERENCES users(id),
  description             TEXT NOT NULL,
  item_count              INTEGER NOT NULL DEFAULT 1 CHECK (item_count >= 0 AND item_count <= 10000),
  status                  TEXT NOT NULL CHECK (status IN ('EXPECTED', 'ARRIVED', 'AWAITING_AUTHORIZATION', 'AUTHORIZED', 'RECEIVED', 'DEPARTED', 'REJECTED', 'CANCELLED', 'RETURNED')),
  requires_authorization  INTEGER NOT NULL DEFAULT 1 CHECK (requires_authorization IN (0, 1)),
  expected_at             TEXT,
  arrived_at              TEXT,
  authorized_by           INTEGER REFERENCES users(id),
  authorized_at           TEXT,
  authorization_note      TEXT,
  received_by_user_id     INTEGER REFERENCES users(id),
  received_by_name        TEXT,
  received_at             TEXT,
  receipt_note            TEXT,
  departed_at             TEXT,
  departed_gate_id        INTEGER REFERENCES gates(id),
  status_reason           TEXT,
  notes                   TEXT,
  created_by              INTEGER NOT NULL REFERENCES users(id),
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  UNIQUE (organization_id, reference)
);
CREATE INDEX deliveries_location_status ON deliveries (location_id, status);
CREATE INDEX deliveries_recipient ON deliveries (recipient_user_id, status);
CREATE INDEX deliveries_arrived ON deliveries (location_id, arrived_at);

CREATE TABLE delivery_status_history (
  id             INTEGER PRIMARY KEY,
  delivery_id    INTEGER NOT NULL REFERENCES deliveries(id),
  from_status    TEXT,
  to_status      TEXT NOT NULL,
  reason         TEXT,
  actor_user_id  INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL
);
CREATE INDEX delivery_status_history_delivery ON delivery_status_history (delivery_id, created_at);

-- ---------------------------------------------------------------------------
-- Gate verification, manual review & movement events
-- ---------------------------------------------------------------------------

CREATE TABLE verification_attempts (
  id                   INTEGER PRIMARY KEY,
  organization_id      INTEGER NOT NULL REFERENCES organizations(id),
  location_id          INTEGER NOT NULL REFERENCES locations(id),
  gate_id              INTEGER NOT NULL REFERENCES gates(id),
  operator_user_id     INTEGER REFERENCES users(id),
  mode                 TEXT NOT NULL CHECK (mode IN ('PERSONNEL', 'VISITOR', 'CONTRACTOR', 'TEMPORARY', 'VEHICLE', 'DELIVERY')),
  method               TEXT NOT NULL,
  input_fingerprint    TEXT NOT NULL,
  input_display        TEXT NOT NULL,
  result_code          TEXT NOT NULL,
  subject_type         TEXT,
  subject_id           INTEGER,
  category             TEXT,
  credential_id        INTEGER REFERENCES credentials(id),
  visit_id             INTEGER REFERENCES visits(id),
  pass_id              INTEGER REFERENCES visit_passes(id),
  temporary_access_id  INTEGER REFERENCES temporary_access(id),
  contractor_id        INTEGER REFERENCES contractors(id),
  vehicle_id           INTEGER REFERENCES vehicles(id),
  delivery_id          INTEGER REFERENCES deliveries(id),
  presence_state       TEXT,
  allowed_actions      TEXT NOT NULL DEFAULT '[]',
  detail               TEXT,
  created_at           TEXT NOT NULL
);
CREATE INDEX verification_attempts_gate_time ON verification_attempts (gate_id, created_at);
CREATE INDEX verification_attempts_location_result ON verification_attempts (location_id, result_code, created_at);
CREATE INDEX verification_attempts_fingerprint ON verification_attempts (input_fingerprint, created_at);

CREATE TABLE manual_reviews (
  id                       INTEGER PRIMARY KEY,
  organization_id          INTEGER NOT NULL REFERENCES organizations(id),
  reference                TEXT NOT NULL,
  location_id              INTEGER NOT NULL REFERENCES locations(id),
  gate_id                  INTEGER NOT NULL REFERENCES gates(id),
  verification_attempt_id  INTEGER NOT NULL UNIQUE REFERENCES verification_attempts(id),
  requested_action         TEXT NOT NULL CHECK (requested_action IN ('ENTRY', 'EXIT')),
  requested_by             INTEGER NOT NULL REFERENCES users(id),
  request_note             TEXT NOT NULL,
  status                   TEXT NOT NULL CHECK (status IN ('PENDING', 'APPROVED', 'DECLINED', 'USED', 'EXPIRED')),
  decided_by               INTEGER REFERENCES users(id),
  decided_at               TEXT,
  decision_note            TEXT,
  event_id                 INTEGER,
  created_at               TEXT NOT NULL,
  updated_at               TEXT NOT NULL,
  UNIQUE (organization_id, reference)
);
CREATE INDEX manual_reviews_location_status ON manual_reviews (location_id, status);

CREATE TABLE movement_events (
  id                       INTEGER PRIMARY KEY,
  organization_id          INTEGER NOT NULL REFERENCES organizations(id),
  reference                TEXT NOT NULL UNIQUE,
  location_id              INTEGER NOT NULL REFERENCES locations(id),
  gate_id                  INTEGER NOT NULL REFERENCES gates(id),
  event_type               TEXT NOT NULL CHECK (event_type IN ('ENTRY', 'EXIT')),
  subject_type             TEXT NOT NULL CHECK (subject_type IN ('PERSONNEL', 'VISITOR', 'CONTRACTOR', 'TEMPORARY', 'DELIVERY', 'VEHICLE')),
  subject_id               INTEGER NOT NULL,
  category                 TEXT NOT NULL,
  visit_id                 INTEGER REFERENCES visits(id),
  pass_id                  INTEGER REFERENCES visit_passes(id),
  credential_id            INTEGER REFERENCES credentials(id),
  temporary_access_id      INTEGER REFERENCES temporary_access(id),
  contractor_id            INTEGER REFERENCES contractors(id),
  delivery_id              INTEGER REFERENCES deliveries(id),
  vehicle_id               INTEGER REFERENCES vehicles(id),
  linked_subject_type      TEXT,
  linked_subject_id        INTEGER,
  driver_reference         TEXT,
  purpose                  TEXT,
  sponsoring_department    TEXT,
  verification_attempt_id  INTEGER UNIQUE REFERENCES verification_attempts(id),
  manual_review_id         INTEGER REFERENCES manual_reviews(id),
  correction_id            INTEGER REFERENCES event_corrections(id),
  verification_method      TEXT NOT NULL,
  outcome                  TEXT NOT NULL CHECK (outcome IN ('RECORDED', 'RECORDED_AFTER_REVIEW', 'CORRECTION_ENTRY')),
  operator_user_id         INTEGER REFERENCES users(id),
  idempotency_key          TEXT UNIQUE,
  notes                    TEXT,
  reported_occurred_at     TEXT,
  recorded_at              TEXT NOT NULL
);
CREATE INDEX movement_events_subject ON movement_events (subject_type, subject_id, id);
CREATE INDEX movement_events_location_time ON movement_events (location_id, recorded_at);
CREATE INDEX movement_events_gate_time ON movement_events (gate_id, recorded_at);
CREATE INDEX movement_events_category_time ON movement_events (category, recorded_at);
CREATE INDEX movement_events_visit ON movement_events (visit_id);

CREATE TABLE event_corrections (
  id                INTEGER PRIMARY KEY,
  organization_id   INTEGER NOT NULL REFERENCES organizations(id),
  reference         TEXT NOT NULL UNIQUE,
  location_id       INTEGER NOT NULL REFERENCES locations(id),
  correction_type   TEXT NOT NULL CHECK (correction_type IN ('VOID_EVENT', 'RECORD_MISSING_EVENT')),
  voided_event_id   INTEGER UNIQUE REFERENCES movement_events(id),
  subject_type      TEXT NOT NULL,
  subject_id        INTEGER NOT NULL,
  reason            TEXT NOT NULL,
  exception_id      INTEGER,
  requested_by      INTEGER NOT NULL REFERENCES users(id),
  created_at        TEXT NOT NULL,
  CHECK ((correction_type = 'VOID_EVENT') = (voided_event_id IS NOT NULL))
);
CREATE INDEX event_corrections_subject ON event_corrections (subject_type, subject_id);

CREATE TRIGGER movement_events_no_update BEFORE UPDATE ON movement_events
BEGIN SELECT RAISE(ABORT, 'movement_events are append-only; record a correction instead'); END;
CREATE TRIGGER movement_events_no_delete BEFORE DELETE ON movement_events
BEGIN SELECT RAISE(ABORT, 'movement_events are append-only; record a correction instead'); END;
CREATE TRIGGER event_corrections_no_update BEFORE UPDATE ON event_corrections
BEGIN SELECT RAISE(ABORT, 'event_corrections are append-only'); END;
CREATE TRIGGER event_corrections_no_delete BEFORE DELETE ON event_corrections
BEGIN SELECT RAISE(ABORT, 'event_corrections are append-only'); END;

-- Current recorded state per subject. Derived exclusively from valid
-- (non-voided) movement events by the event service; never edited directly.
CREATE TABLE presence (
  subject_type     TEXT NOT NULL,
  subject_id       INTEGER NOT NULL,
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  state            TEXT NOT NULL CHECK (state IN ('INSIDE', 'OUTSIDE')),
  category         TEXT NOT NULL,
  location_id      INTEGER REFERENCES locations(id),
  gate_id          INTEGER REFERENCES gates(id),
  last_event_id    INTEGER REFERENCES movement_events(id),
  since            TEXT,
  updated_at       TEXT NOT NULL,
  PRIMARY KEY (subject_type, subject_id)
);
CREATE INDEX presence_location_state ON presence (location_id, state, category);

-- ---------------------------------------------------------------------------
-- Alerts, administrative exceptions, handovers & notifications
-- ---------------------------------------------------------------------------

CREATE TABLE alerts (
  id                       INTEGER PRIMARY KEY,
  organization_id          INTEGER NOT NULL REFERENCES organizations(id),
  reference                TEXT NOT NULL,
  location_id              INTEGER REFERENCES locations(id),
  gate_id                  INTEGER REFERENCES gates(id),
  alert_type               TEXT NOT NULL,
  severity                 TEXT NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  status                   TEXT NOT NULL CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED')),
  title                    TEXT NOT NULL,
  description              TEXT NOT NULL,
  related_type             TEXT,
  related_id               INTEGER,
  related_reference        TEXT,
  verification_attempt_id  INTEGER REFERENCES verification_attempts(id),
  event_id                 INTEGER REFERENCES movement_events(id),
  dedupe_key               TEXT,
  occurrence_count         INTEGER NOT NULL DEFAULT 1,
  first_seen_at            TEXT NOT NULL,
  last_seen_at             TEXT NOT NULL,
  assigned_user_id         INTEGER REFERENCES users(id),
  acknowledged_by          INTEGER REFERENCES users(id),
  acknowledged_at          TEXT,
  acknowledgement_note     TEXT,
  resolved_by              INTEGER REFERENCES users(id),
  resolved_at              TEXT,
  resolution_note          TEXT,
  created_at               TEXT NOT NULL,
  updated_at               TEXT NOT NULL,
  UNIQUE (organization_id, reference)
);
CREATE UNIQUE INDEX alerts_open_dedupe ON alerts (dedupe_key) WHERE status <> 'RESOLVED' AND dedupe_key IS NOT NULL;
CREATE INDEX alerts_location_status ON alerts (location_id, status, created_at);
CREATE INDEX alerts_type ON alerts (alert_type, created_at);

CREATE TABLE alert_history (
  id             INTEGER PRIMARY KEY,
  alert_id       INTEGER NOT NULL REFERENCES alerts(id),
  action         TEXT NOT NULL,
  note           TEXT,
  actor_user_id  INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL
);
CREATE INDEX alert_history_alert ON alert_history (alert_id, created_at);

CREATE TABLE admin_exceptions (
  id                   INTEGER PRIMARY KEY,
  organization_id      INTEGER NOT NULL REFERENCES organizations(id),
  reference            TEXT NOT NULL,
  location_id          INTEGER NOT NULL REFERENCES locations(id),
  category             TEXT NOT NULL,
  related_type         TEXT,
  related_id           INTEGER,
  related_reference    TEXT,
  title                TEXT NOT NULL,
  description          TEXT NOT NULL,
  responsible_role     TEXT,
  responsible_user_id  INTEGER REFERENCES users(id),
  status               TEXT NOT NULL CHECK (status IN ('OPEN', 'UNDER_REVIEW', 'RESOLVED')),
  created_by           INTEGER REFERENCES users(id),
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  resolution_note      TEXT,
  resolved_by          INTEGER REFERENCES users(id),
  resolved_at          TEXT,
  UNIQUE (organization_id, reference),
  CHECK (status <> 'RESOLVED' OR (resolution_note IS NOT NULL AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL))
);
CREATE INDEX admin_exceptions_location_status ON admin_exceptions (location_id, status);

CREATE TABLE admin_exception_history (
  id             INTEGER PRIMARY KEY,
  exception_id   INTEGER NOT NULL REFERENCES admin_exceptions(id),
  from_status    TEXT,
  to_status      TEXT NOT NULL,
  note           TEXT,
  actor_user_id  INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL
);

CREATE TABLE handovers (
  id                INTEGER PRIMARY KEY,
  organization_id   INTEGER NOT NULL REFERENCES organizations(id),
  reference         TEXT NOT NULL,
  location_id       INTEGER NOT NULL REFERENCES locations(id),
  gate_id           INTEGER REFERENCES gates(id),
  shift_label       TEXT NOT NULL,
  handed_over_by    INTEGER NOT NULL REFERENCES users(id),
  handed_over_to    INTEGER REFERENCES users(id),
  summary_json      TEXT NOT NULL,
  notes             TEXT,
  created_at        TEXT NOT NULL,
  acknowledged_by   INTEGER REFERENCES users(id),
  acknowledged_at   TEXT,
  UNIQUE (organization_id, reference)
);
CREATE INDEX handovers_location ON handovers (location_id, created_at);

CREATE TABLE notifications (
  id               INTEGER PRIMARY KEY,
  organization_id  INTEGER NOT NULL REFERENCES organizations(id),
  user_id          INTEGER NOT NULL REFERENCES users(id),
  location_id      INTEGER REFERENCES locations(id),
  type             TEXT NOT NULL,
  title            TEXT NOT NULL,
  body             TEXT NOT NULL,
  link             TEXT,
  related_type     TEXT,
  related_id       INTEGER,
  channel          TEXT NOT NULL DEFAULT 'IN_APP',
  created_at       TEXT NOT NULL,
  read_at          TEXT
);
CREATE INDEX notifications_user ON notifications (user_id, read_at, created_at);

-- ---------------------------------------------------------------------------
-- Audit trail (append-only, hash-chained for tamper evidence)
-- ---------------------------------------------------------------------------

CREATE TABLE audit_events (
  id               INTEGER PRIMARY KEY,
  organization_id  INTEGER,
  location_id      INTEGER,
  actor_user_id    INTEGER,
  actor_username   TEXT NOT NULL,
  actor_role       TEXT,
  action           TEXT NOT NULL,
  entity_type      TEXT,
  entity_id        TEXT,
  entity_ref       TEXT,
  outcome          TEXT NOT NULL CHECK (outcome IN ('SUCCESS', 'DENIED', 'FAILURE')),
  metadata         TEXT,
  ip               TEXT,
  created_at       TEXT NOT NULL,
  prev_hash        TEXT,
  hash             TEXT NOT NULL
);
CREATE INDEX audit_events_time ON audit_events (created_at);
CREATE INDEX audit_events_entity ON audit_events (entity_type, entity_id);
CREATE INDEX audit_events_actor ON audit_events (actor_user_id, created_at);
CREATE INDEX audit_events_location ON audit_events (location_id, created_at);
CREATE INDEX audit_events_action ON audit_events (action, created_at);

CREATE TRIGGER audit_events_no_update BEFORE UPDATE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events are append-only'); END;
CREATE TRIGGER audit_events_no_delete BEFORE DELETE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events are append-only'); END;

-- ---------------------------------------------------------------------------
-- Application metadata (seed markers, schema notes)
-- ---------------------------------------------------------------------------

CREATE TABLE app_meta (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
